mapper.update:
UPDATE orders SET pg_order_id = #{pgOrderId}
WHERE
order_no = #{orderNo}

UPDATE orders SET receiver_name = #{receiverName}, receiver_phone_number = #{receiverPhoneNumber}, receiver_zip_code = #{receiverZipCode}, receiver_base_address = #{receiverBaseAddress}, receiver_detail_address = #{receiverDetailAddress},
order_amount = #{orderAmount},
coupon_discount_amount = #{couponDiscountAmount}, total_price = #{totalPrice}, message = #{message} WHERE order_no = #{orderNo}

UPDATE product_option
SET stock = stock + #{quantity}
WHERE product_option_no = #{productOptionNo}

mapper.select:
SELECT * FROM ( SELECT o.order_no AS orderNo, o.member_no AS memberNo, o.total_price AS totalPrice, o.order_status AS orderStatus, o.created_at AS createdAt,
(SELECT pi.image_url FROM product_img pi INNER JOIN product_option po ON pi.product_no = po.product_no INNER JOIN order_item oi2 ON po.product_option_no = oi2.product_option_no WHERE oi2.order_no = o.order_no AND pi.image_type = 'THUMB' AND ROWNUM = 1) AS mainImageUrl,
(SELECT oi3.item_name FROM order_item oi3 WHERE oi3.order_no = o.order_no AND ROWNUM = 1) AS mainProductName,
(SELECT SUM(quantity) FROM order_item oi4 WHERE oi4.order_no = o.order_no) AS totalQuantity,
ROW_NUMBER() OVER (ORDER BY o.created_at DESC) AS rn FROM orders o WHERE o.member_no = #{memberNo}
) WHERE rn BETWEEN #{req.offset} + 1 AND #{req.offset} + #{req.size}
